class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

    def startsWith(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

    def delete(self, word):
        def _delete(node, i):
            if i == len(word):
                node.is_end = False
                return len(node.children) == 0
            char = word[i]
            if char not in node.children:
                return False
            should_delete = _delete(node.children[char], i + 1)
            if should_delete:
                del node.children[char]
            return not node.is_end and len(node.children) == 0
        _delete(self.root, 0)
